DROP TABLE IF EXISTS `tb_planos_cuidado`;
CREATE TABLE `tb_planos_cuidado` (
  `id` int NOT NULL AUTO_INCREMENT,
  `uuid` char(36) COLLATE utf8mb4_general_ci NOT NULL,
  `paciente_id` int NOT NULL,
  `modelo_chave` varchar(80) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `titulo` varchar(180) COLLATE utf8mb4_general_ci NOT NULL,
  `subtitulo` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `responsavel_tecnico` varchar(120) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `data_inicio` date NOT NULL,
  `data_revisao` date DEFAULT NULL,
  `status` enum('Rascunho','Ativo','Revisado','Arquivado') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'Rascunho',
  `versao` int NOT NULL DEFAULT '1',
  `resumo_clinico` text COLLATE utf8mb4_general_ci,
  `objetivos` text COLLATE utf8mb4_general_ci,
  `monitoramento` text COLLATE utf8mb4_general_ci,
  `oxigenoterapia` text COLLATE utf8mb4_general_ci,
  `nebulizacao` text COLLATE utf8mb4_general_ci,
  `controle_ambiental` text COLLATE utf8mb4_general_ci,
  `alimentacao_hidratacao` text COLLATE utf8mb4_general_ci,
  `atividade_repouso` text COLLATE utf8mb4_general_ci,
  `medicamentos` text COLLATE utf8mb4_general_ci,
  `comunicacao_familia` text COLLATE utf8mb4_general_ci,
  `sinais_alerta` text COLLATE utf8mb4_general_ci,
  `observacoes` text COLLATE utf8mb4_general_ci,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_planos_cuidado_uuid` (`uuid`),
  KEY `idx_planos_cuidado_paciente` (`paciente_id`),
  KEY `idx_planos_cuidado_status` (`status`),
  KEY `idx_planos_cuidado_modelo` (`modelo_chave`),
  CONSTRAINT `fk_planos_cuidado_paciente` FOREIGN KEY (`paciente_id`) REFERENCES `tb_pacientes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Dados da tabela tb_planos_cuidado

INSERT INTO `tb_planos_cuidado` (`id`, `uuid`, `paciente_id`, `modelo_chave`, `titulo`, `subtitulo`, `responsavel_tecnico`, `data_inicio`, `data_revisao`, `status`, `versao`, `resumo_clinico`, `objetivos`, `monitoramento`, `oxigenoterapia`, `nebulizacao`, `controle_ambiental`, `alimentacao_hidratacao`, `atividade_repouso`, `medicamentos`, `comunicacao_familia`, `sinais_alerta`, `observacoes`, `created_at`, `updated_at`) VALUES
(1, '72c39bae-6cac-4946-8f7f-0f6ec21912ee', 16, 'respiratorio', 'Plano de Cuidados Home Care — Arthur Mendes', 'Crise asmática (J45) | 7 anos | Independente | Preservado', 'Vanusa', '2026-06-03', '2026-06-30', 'Rascunho', 1, 'Paciente: Arthur Mendes\r\nDiagnóstico: Crise asmática\r\nCID: J45\r\nIdade: 7 anos\r\nMobilidade: Independente\r\nCognição: Preservado\r\nVia alimentar: VO\r\nDispositivo/condição relevante: usa oxigênio.', 'Manter estabilidade respiratória, reduzir risco de crise, reconhecer sinais precoces de desconforto e garantir comunicação rápida com família/equipe.', 'Avaliar frequência respiratória, padrão ventilatório e sinais de esforço em cada plantão. Registrar presença de chiado, tosse persistente, cansaço, tiragem, cianose ou queda de saturação quando houver oxímetro disponível.', 'Manter equipamento de oxigênio disponível e funcionando. Verificar disponibilidade do cilindro/concentrador e acessórios. Usar oxigênio somente conforme prescrição/orientação profissional. Registrar uso, horário e resposta.', 'Realizar nebulização conforme prescrição/orientação registrada. Higienizar equipamento após cada uso. Observar resposta clínica e registrar horário, medicamento/solução e evolução dos sintomas.', 'Manter ambiente livre de gatilhos respiratórios: poeira, mofo, fumaça, perfumes fortes, sprays, produtos de limpeza com odor intenso, tapetes e excesso de pelúcias. Ventilar sem exposição direta a frio intenso.', 'Via alimentar informada: VO. Incentivar hidratação conforme orientação. Observar refluxo, engasgos ou recusa alimentar, pois podem piorar sintomas respiratórios em alguns pacientes.', 'Evitar esforço físico em dias de crise ou desconforto respiratório. Favorecer repouso em posição confortável, com cabeceira elevada quando indicado e tolerado.', 'Conferir medicações respiratórias conforme prescrição. Manter medicação de resgate acessível quando prescrita e dentro da validade. Nunca administrar medicamento fora da prescrição.', 'Orientar comunicação imediata com Simone Mendes (32988885555) diante de piora respiratória, crise sem resposta à conduta prescrita, sonolência incomum, cianose ou dificuldade importante para falar/chorar.', 'Acionar serviço de urgência se houver cianose, perda de consciência, dificuldade respiratória intensa, piora rápida, saturação muito baixa quando monitorada ou ausência de resposta às medidas prescritas.', '', '2026-06-03 16:59:54', '2026-06-03 23:54:23');
-- 1 registro(s) exportado(s) de tb_planos_cuidado

